//! memchr, memrchr, memmem — byte search positions and found spans.

c_run_cases! {
    memchr_finds_first_byte => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char *p=memchr(\"abcd\", 'c', 4); printf(\"%s\\n\", p); return 0;", expect: ["cd"] },
    memchr_not_found_returns_null => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memchr(\"abcd\", 'z', 4)==NULL); return 0;", expect: ["1"] },
    memchr_zero_length_returns_null => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memchr(\"abc\", 'a', 0)==NULL); return 0;", expect: ["1"] },
    memchr_at_start => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"zap\";", body: "printf(\"%d\\n\", (int)(memchr(h, 'z', 3) - h)); return 0;", expect: ["0"] },
    memchr_at_last_index => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%c\\n\", *memchr(\"abca\", 'a', 4)); return 0;", expect: ["a"] },
    memchr_null_byte_search => { includes: ["<stdio.h>", "<string.h>"], decls: "char b[4]={'a','b',0,'d'};", body: "char *p=memchr(b, 0, 4); printf(\"%d\\n\", (int)(p-b)); return 0;", expect: ["2"] },
    memchr_digit_byte => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memchr(\"id5\", '5', 3)); return 0;", expect: ["5"] },
    memchr_space_byte => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memchr(\"a b\", ' ', 3)); return 0;", expect: [" b"] },
    memchr_partial_buffer => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memchr(\"hello\", 'l', 2)==NULL); return 0;", expect: ["1"] },
    memchr_returns_pointer_into_buffer => { includes: ["<stdio.h>", "<string.h>"], decls: "char buf[6]=\"kite\";", body: "char *p=memchr(buf, 't', 4); printf(\"%c\\n\", *p); return 0;", expect: ["t"] },
    memchr_uppercase_match => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memchr(\"AbC\", 'B', 3)); return 0;", expect: ["bC"] },
    memchr_first_of_duplicates => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"banana\";", body: "printf(\"%d\\n\", (int)(memchr(h, 'a', 6) - h)); return 0;", expect: ["1"] },
    memchr_exclamation => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memchr(\"ok!\", '!', 3)); return 0;", expect: ["!"] },
    memchr_n_equals_one => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%c\\n\", *memchr(\"xy\", 'x', 1)); return 0;", expect: ["x"] },
    memchr_n_larger_than_content => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memchr(\"a\", 'a', 10)!=NULL); return 0;", expect: ["1"] },
    memrchr_finds_last_occurrence => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"abca\";", body: "printf(\"%d\\n\", (int)(memrchr(h, 'a', 4) - h)); return 0;", expect: ["3"] },
    memrchr_single_byte_buffer => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%c\\n\", *memrchr(\"x\", 'x', 1)); return 0;", expect: ["x"] },
    memrchr_not_found => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memrchr(\"abcd\", 'z', 4)==NULL); return 0;", expect: ["1"] },
    memrchr_zero_len => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memrchr(\"abc\", 'c', 0)==NULL); return 0;", expect: ["1"] },
    memrchr_last_is_only => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"zzz\";", body: "printf(\"%d\\n\", (int)(memrchr(h, 'z', 3) - h)); return 0;", expect: ["2"] },
    memrchr_digit_last => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memrchr(\"ab12\", '2', 4)); return 0;", expect: ["2"] },
    memrchr_space_last => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memrchr(\"a b c\", ' ', 5)); return 0;", expect: [" c"] },
    memrchr_partial_range => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"aabaa\";", body: "printf(\"%d\\n\", memrchr(h, 'a', 3)==h+1); return 0;", expect: ["1"] },
    memrchr_in_char_array => { includes: ["<stdio.h>", "<string.h>"], decls: "unsigned char b[5]={1,2,3,2,1};", body: "unsigned char *p=memrchr(b, 2, 5); printf(\"%d\\n\", (int)(p-b)); return 0;", expect: ["3"] },
    memrchr_null_byte => { includes: ["<stdio.h>", "<string.h>"], decls: "char b[3]={'a',0,'b'};", body: "char *p=memrchr(b, 0, 3); printf(\"%d\\n\", (int)(p-b)); return 0;", expect: ["1"] },
    memrchr_unique_char_position => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"q\";", body: "printf(\"%d\\n\", (int)(memrchr(h, 'q', 1) - h)); return 0;", expect: ["0"] },
    memrchr_dot_byte => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memrchr(\"a.b.c\", '.', 5)); return 0;", expect: [".c"] },
    memrchr_n_one => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%c\\n\", *memrchr(\"yz\", 'y', 1)); return 0;", expect: ["y"] },
    memrchr_skips_beyond_n => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"aaa\";", body: "printf(\"%d\\n\", memrchr(h, 'a', 2)==h+1); return 0;", expect: ["1"] },
    memrchr_returns_suffix => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memrchr(\"prefix_x\", '_', 8)); return 0;", expect: ["_x"] },
    memmem_finds_substring => { includes: ["<stdio.h>", "<string.h>"], decls: "char *h=\"abcdef\"; char *n=\"cd\";", body: "char *p=memmem(h,6,n,2); printf(\"%s\\n\", p); return 0;", expect: ["cdef"] },
    memmem_not_found => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memmem(\"abc\",3,\"z\",1)==NULL); return 0;", expect: ["1"] },
    memmem_empty_needle_at_start => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"hi\";", body: "printf(\"%d\\n\", (int)(memmem(h,2,\"\",0) - h)); return 0;", expect: ["0"] },
    memmem_needle_equals_haystack => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memmem(\"xy\",2,\"xy\",2)!=(char*)0); return 0;", expect: ["1"] },
    memmem_single_byte_needle => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memmem(\"banana\",6,\"n\",1)); return 0;", expect: ["nana"] },
    memmem_at_end => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memmem(\"foot\",4,\"ot\",2)); return 0;", expect: ["ot"] },
    memmem_offset_position => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"123412\";", body: "printf(\"%d\\n\", (int)(memmem(h,6,\"34\",2)-h)); return 0;", expect: ["2"] },
    memmem_longer_needle_no_match => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memmem(\"ab\",2,\"abc\",3)==NULL); return 0;", expect: ["1"] },
    memmem_repeated_pattern => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memmem(\"aaaa\",4,\"aaa\",3)); return 0;", expect: ["aaaa"] },
    memmem_binary_with_null => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[4]={'a',0,'b',0};", body: "char *p=memmem(h,4,\"\\0b\",2); printf(\"%d\\n\", p!=NULL); return 0;", expect: ["1"] },
    memmem_digit_sequence => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memmem(\"id99end\",7,\"99\",2)); return 0;", expect: ["99end"] },
    memmem_first_occurrence => { includes: ["<stdio.h>", "<string.h>"], decls: "char h[]=\"abcabc\";", body: "printf(\"%d\\n\", (int)(memmem(h,6,\"bc\",2)-h)); return 0;", expect: ["1"] },
    memmem_zero_haystack => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memmem(\"\",0,\"a\",1)==NULL); return 0;", expect: ["1"] },
    memmem_zero_needle_nonempty_hay => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memmem(\"x\",1,\"\",0)!=(char*)0); return 0;", expect: ["1"] },
    memmem_case_sensitive => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", memmem(\"Ab\",2,\"ab\",2)==NULL); return 0;", expect: ["1"] },
    memmem_partial_overlap => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%s\\n\", memmem(\"ababa\",5,\"bab\",3)); return 0;", expect: ["baba"] },
}
